using Crown.Core;
using System.Text.Json.Nodes;

internal static class StageTwentySpecs
{
    private static void Assert(bool value,string message){if(!value)throw new Exception(message);}
    internal static (GameState S,City C,int[] Sites) Fixture()
    {
        var s=World.CreateLegacy();Narrative.Resolve(s,0);var c=s.Cities.First(v=>v.Owner==0);c.Population=8;c.Project="granary";s.Player.Gold=10000;
        s.Player.Technologies.UnionWith(Districts.Types.Select(t=>t.Technology));foreach(var city in s.Cities)city.ProductionPaused=city!=c;
        foreach(var t in s.Tiles.Where(t=>t.Owner==0&&t.Id!=c.Tile&&World.Distance(t,s.Tiles[c.Tile])<=2)){t.Explored=true;t.Terrain=Terrain.Grassland;t.Resource=Resource.None;t.Improvement=Improvement.None;t.Ruin=false;t.River=false;}
        return(s,c,s.Tiles.Where(t=>t.Owner==0&&t.Id!=c.Tile&&World.Distance(t,s.Tiles[c.Tile])<=2).Select(t=>t.Id).ToArray());
    }
    private static District Active(GameState s,City c,int tile,DistrictKind kind,DistrictFunding funding=DistrictFunding.Public)
    {Assert(Districts.Begin(s,c.Id,tile,kind,funding).Success,"Begin failed");var d=s.Districts.Last();d.Status=DistrictStatus.Active;return d;}
    private static void Reject(GameState s,Action<JsonObject> change)
    {var node=JsonNode.Parse(SaveGame.Serialize(s))!.AsObject();change(node);bool rejected=false;try{SaveGame.Deserialize(node.ToJsonString());}catch(Exception ex)when(ex is InvalidDataException or System.Text.Json.JsonException){rejected=true;}Assert(rejected,"Invalid save accepted");}
    public static void Run(Action<string,Action> test)
    {
        test("District placement reserves an actual field and charges public financing once",()=>{var(s,c,sites)=Fixture();int tile=Engine.WorkedTiles(s,c).First().Id;double gold=s.Player.Gold;Assert(Districts.Begin(s,c.Id,tile,DistrictKind.Gardens,DistrictFunding.Public).Success,"Plan rejected");Assert(s.Player.Gold==gold-30&&s.Districts.Single().Tile==tile&&!Engine.WorkedTiles(s,c).Any(t=>t.Id==tile),"No real cost or land reservation");var before=SaveGame.Serialize(s);Assert(!Districts.Begin(s,c.Id,tile,DistrictKind.Gardens,DistrictFunding.Public).Success&&SaveGame.Serialize(s)==before,"Repeated plan changed state");});
        test("District legality rejects resources improvements ruins cities and foreign territory atomically",()=>{foreach(int mode in Enumerable.Range(0,6)){var(s,c,sites)=Fixture();int id=sites[0];var t=s.Tiles[id];switch(mode){case 0:t.Resource=Resource.Iron;break;case 1:t.Improvement=Improvement.Farm;break;case 2:t.Ruin=true;break;case 3:id=c.Tile;break;case 4:t.Owner=1;break;case 5:t.Explored=false;break;}string before=SaveGame.Serialize(s);Assert(!Districts.Begin(s,c.Id,id,DistrictKind.Gardens,DistrictFunding.Public).Success&&SaveGame.Serialize(s)==before,"Illegal district mutated the world");}});
        test("District placement requires knowledge money free construction and population slots",()=>{var(s,c,sites)=Fixture();s.Player.Technologies.Clear();Assert(!Districts.Begin(s,c.Id,sites[0],DistrictKind.Gardens,DistrictFunding.Public).Success,"Missing technology ignored");s.Player.Technologies.Add("agriculture");s.Player.Gold=29;Assert(!Districts.Begin(s,c.Id,sites[0],DistrictKind.Gardens,DistrictFunding.Public).Success,"Free survey");s.Player.Gold=1000;c.Population=3;Active(s,c,sites[0],DistrictKind.Gardens);s.Player.Technologies.Add("mining");Assert(!Districts.Begin(s,c.Id,sites[1],DistrictKind.Workshops,DistrictFunding.Public).Success,"Population limit ignored");});
        test("Guild and public charters have different lasting yields costs and political effects",()=>{var(a,ca,ta)=Fixture();var(b,cb,tb)=Fixture();var da=Active(a,ca,ta[0],DistrictKind.Scholars);var db=Active(b,cb,tb[0],DistrictKind.Scholars,DistrictFunding.Guild);var ya=Districts.Yields(a,ca);var yb=Districts.Yields(b,cb);Assert(Math.Abs(yb.Science-ya.Science*.85)<1e-8&&Districts.Upkeep(db)==Districts.Upkeep(da)*.5&&b.Player.Gold-a.Player.Gold==20,"Charters equivalent");Assert(a.Player.Commons>b.Player.Commons&&a.Player.Nobles<b.Player.Nobles,"Politics missing");});
        test("District adjacency responds to mountains forests rivers roads and workshops resources",()=>{var(s,c,t)=Fixture();int id=t[0];var ns=World.Neighbors(s,id).ToArray();foreach(var n in ns){n.Explored=true;n.Terrain=Terrain.Grassland;n.Resource=Resource.None;n.Road=false;n.River=false;}double baseline=Districts.Preview(s,c,id,DistrictKind.Scholars,DistrictFunding.Public).Science;ns[0].Terrain=Terrain.Mountain;ns[1].Terrain=Terrain.Forest;Assert(Districts.Preview(s,c,id,DistrictKind.Scholars,DistrictFunding.Public).Science>baseline,"No science geography");double workshop=Districts.Preview(s,c,id,DistrictKind.Workshops,DistrictFunding.Public).Production;ns[2].Resource=Resource.Iron;Assert(Districts.Preview(s,c,id,DistrictKind.Workshops,DistrictFunding.Public).Production>workshop,"No ore adjacency");double trade=Districts.Preview(s,c,id,DistrictKind.Exchange,DistrictFunding.Public).Gold;s.Tiles[id].River=true;ns[3].Road=true;ns[3].RoadOwner=0;Assert(Districts.Preview(s,c,id,DistrictKind.Exchange,DistrictFunding.Public).Gold>trade,"No trade geography");});
        test("Unknown neighboring terrain never contributes to the player's preview",()=>{var(s,c,t)=Fixture();var n=World.Neighbors(s,t[0]).First();n.Explored=false;n.Terrain=Terrain.Grassland;double before=Districts.Preview(s,c,t[0],DistrictKind.Scholars,DistrictFunding.Public).Science;n.Terrain=Terrain.Mountain;Assert(Districts.Preview(s,c,t[0],DistrictKind.Scholars,DistrictFunding.Public).Science==before,"Preview reveals hidden mountains");});
        test("Construction diverts exactly the allocated production from the ordinary project",()=>{var(s,c,t)=Fixture();Districts.Begin(s,c.Id,t[0],DistrictKind.Scholars,DistrictFunding.Public);Markets.Tick(s);double production=Engine.CityYields(s,c).Production;Assert(Engine.EndTurn(s).Success,"Turn failed");Assert(Math.Abs(s.Districts.Single().Work-production*.25)<1e-8&&Math.Abs(c.Production-production*.75)<1e-8,"Production created or lost");});
        test("Finishing a district returns unused allocation to the ordinary project",()=>{var(s,c,t)=Fixture();Districts.Begin(s,c.Id,t[0],DistrictKind.Workshops,DistrictFunding.Public);var d=s.Districts.Single();d.Work=Districts.Cost(d)-.5;Districts.SetShare(s,c.Id,100);Markets.Tick(s);double production=Engine.CityYields(s,c).Production;Engine.EndTurn(s);Assert(d.Status==DistrictStatus.Active&&d.Work==0&&Math.Abs(c.Production-(production-.5))<1e-8,"Completion lost overflow");});
        test("Paused production and zero allocation preserve district work",()=>{var(s,c,t)=Fixture();Districts.Begin(s,c.Id,t[0],DistrictKind.Forum,DistrictFunding.Public);c.ProductionPaused=true;Engine.EndTurn(s);Assert(s.Districts[0].Work==0&&c.Production==0,"Paused construction progressed");c.ProductionPaused=false;Districts.SetShare(s,c.Id,0);s.PendingEvent=null;Engine.EndTurn(s);Assert(s.Districts[0].Work==0&&c.Production>0,"Zero allocation blocked ordinary construction");});
        test("District labor policy allows one actual change per turn",()=>{var(s,c,_)=Fixture();Assert(Districts.SetShare(s,c.Id,50).Success,"Policy failed");string before=SaveGame.Serialize(s);Assert(!Districts.SetShare(s,c.Id,100).Success&&SaveGame.Serialize(s)==before&&!Districts.SetShare(s,c.Id,33).Success,"Policy cooldown or domain bypassed");});
        test("Active districts produce actual city output housing and treasury maintenance",()=>{var(s,c,t)=Fixture();var baseline=Engine.CityYields(s,c);double housing=Regions.Housing(s,c);double costs=Engine.Economy(s,0).AdministrationCost;Active(s,c,t[0],DistrictKind.Gardens);Assert(Districts.Yields(s,c).Food>0&&Regions.Housing(s,c)==housing+2&&Engine.CityYields(s,c).Food>baseline.Food&&Engine.Economy(s,0).AdministrationCost>costs,"District is cosmetic");});
        test("Canceled construction frees its field without refunding money or accumulated work",()=>{var(s,c,t)=Fixture();Districts.Begin(s,c.Id,t[0],DistrictKind.Gardens,DistrictFunding.Guild);s.Districts[0].Work=12;double gold=s.Player.Gold;Assert(Districts.Cancel(s,s.Districts[0].Id).Success&&s.Districts.Count==0&&s.Player.Gold==gold,"Cancellation gave free work or refund");Assert(Engine.Improve(s,t[0],Improvement.Farm).Success,"Reserved field was not released");});
        test("District fields reject improvements while roads can coexist",()=>{var(s,c,t)=Fixture();Districts.Begin(s,c.Id,t[0],DistrictKind.Gardens,DistrictFunding.Public);s.Player.Technologies.Add("pottery");Assert(!Engine.Improve(s,t[0],Improvement.Farm).Success&&Engine.BuildRoad(s,t[0]).Success,"Conflicting land use or missing road support");});
        test("Hostile occupation halts district construction without consuming project production",()=>{var(s,c,t)=Fixture();Districts.Begin(s,c.Id,t[0],DistrictKind.Forum,DistrictFunding.Public);Engine.AddUnit(s,1,t[0],UnitKind.Spearmen);Assert(Districts.Allocation(s,c,20)==0&&Districts.Block(s,s.Districts[0])!=null,"Foreign unit did not block work");});
        test("Wartime pillage disables yields spends movement and grants loot only once",()=>{var(s,c,t)=Fixture();var d=Active(s,c,t[0],DistrictKind.Workshops);var enemy=Engine.AddUnit(s,1,t[0],UnitKind.Spearmen);Assert(!Districts.Pillage(s,enemy.Id,1).Success,"Peaceful pillage accepted");s.Relation(0,1).War=true;double gold=s.Factions[1].Gold;Assert(Districts.Pillage(s,enemy.Id,1).Success&&enemy.Actions==enemy.MaxActions-1&&s.Factions[1].Gold>gold&&d.Status==DistrictStatus.Pillaged&&Districts.Yields(s,c).Production==0,"Pillage lacks effects");string before=SaveGame.Serialize(s);Assert(!Districts.Pillage(s,enemy.Id,1).Success&&SaveGame.Serialize(s)==before,"Repeated loot granted");});
        test("Rebuilding a looted district requires safety and half its original production",()=>{var(s,c,t)=Fixture();var d=Active(s,c,t[0],DistrictKind.Scholars);d.Status=DistrictStatus.Pillaged;var u=Engine.AddUnit(s,1,t[0],UnitKind.Scout);Assert(!Districts.Repair(s,d.Id).Success,"Unsafe repair accepted");s.Units.Remove(u);Assert(Districts.Repair(s,d.Id).Success&&Districts.Cost(d)==Districts.Type(d.Kind).Cost*.5,"Repair cost wrong");d.Work=Districts.Cost(d)-.1;Engine.EndTurn(s);Assert(d.Status==DistrictStatus.Active&&Districts.Yields(s,c).Science>0,"Repair failed to restore services");});
        test("City conquest inherits its district records and future income",()=>{var(s,c,t)=Fixture();var d=Active(s,c,t[0],DistrictKind.Scholars);ProvincialPolitics.Transfer(s,c,1);Assert(s.Districts.Single()==d&&s.Cities.Single(v=>v.Id==d.CityId).Owner==1,"Capture erased district");SaveGame.Deserialize(SaveGame.Serialize(s));});
        test("V20 preserves unfinished work charter allocation and deterministic continuation",()=>{var(s,c,t)=Fixture();Districts.Begin(s,c.Id,t[0],DistrictKind.Scholars,DistrictFunding.Guild);Districts.SetShare(s,c.Id,50);Engine.EndTurn(s);var loaded=SaveGame.Deserialize(SaveGame.Serialize(s));Assert(loaded.Version==20&&SaveGame.Serialize(loaded)==SaveGame.Serialize(s),"District roundtrip diverged");Engine.EndTurn(s);Engine.EndTurn(loaded);Assert(SaveGame.Serialize(s)==SaveGame.Serialize(loaded),"Reload altered future outcome or RNG");});
        test("V19 migration retains campaign and writes an exact predecessor backup",()=>{var(s,c,t)=Fixture();var node=JsonNode.Parse(SaveGame.Serialize(s))!;node["Version"]=19;node.AsObject().Remove("Districts");node.AsObject().Remove("NextDistrictId");string legacy=node.ToJsonString();var loaded=SaveGame.Deserialize(legacy);Assert(loaded.Version==20&&loaded.Districts.Count==0&&loaded.Cities[0].Production==c.Production&&loaded.RandomState==s.RandomState,"Migration invented districts or changed campaign");string folder=Path.Combine(Path.GetTempPath(),"crown-districts-"+Guid.NewGuid());Directory.CreateDirectory(folder);string path=Path.Combine(folder,"campaign.crown");try{File.WriteAllText(path,legacy);SaveGame.Write(loaded,path);Assert(File.ReadAllText(path+".v19.bak")==legacy&&SaveGame.Read(path).Version==20,"V19 backup missing");}finally{File.Delete(path);File.Delete(path+".v19.bak");File.Delete(path+".tmp");Directory.Delete(folder);}});
        test("District save validation rejects forged IDs tiles work enums and duplicate projects",()=>{foreach(int mode in Enumerable.Range(0,9)){var(s,c,t)=Fixture();Districts.Begin(s,c.Id,t[0],DistrictKind.Gardens,DistrictFunding.Public);Reject(s,node=>{var d=node["Districts"]![0]!;switch(mode){case 0:d["Id"]=99;break;case 1:d["CityId"]=-1;break;case 2:d["Tile"]=c.Tile;break;case 3:d["Work"]=999;break;case 4:d["Kind"]="Invalid";break;case 5:d["Status"]="Active";d["Work"]=1;break;case 6:node["Districts"]!.AsArray().Add(d.DeepClone());break;case 7:node["Cities"]![0]!["DistrictShare"]=33;break;case 8:d["FoundedTurn"]=s.Turn+1;break;}});}});
        test("AI uses actual urban sites and paid construction in the full campaign",()=>{var s=World.Create();Narrative.Resolve(s,0);s.Turn=20;foreach(var f in s.Factions.Skip(1)){f.Gold=1000;f.Technologies.UnionWith(EpochCatalog.All.Take(3).SelectMany(e=>e.Technologies));for(int i=0;i<3;i++)f.EpochChoices[i]=0;}foreach(var c in s.Cities)c.Population=8;Assert(Engine.EndTurn(s).Success,"AI turn failed");Assert(s.Districts.Any(d=>s.Cities.Any(c=>c.Id==d.CityId&&c.Owner!=0)),"AI never planned a district");SaveGame.Deserialize(SaveGame.Serialize(s));});
    }
}
